// src/core/controller/crud-controller.ts
function registerCrudController(opts) {
  const { app, path, service, permissions, schemas } = opts;
  const typed = app.withTypeProvider();
  const paginatedResponse = external_exports.object({
    success: external_exports.literal(true),
    data: external_exports.array(schemas.entity),
    meta: external_exports.object({
      page: external_exports.number(),
      limit: external_exports.number(),
      total: external_exports.number(),
      totalPages: external_exports.number(),
      hasNextPage: external_exports.boolean(),
      hasPreviousPage: external_exports.boolean()
    })
  });
  const singleResponse = external_exports.object({ success: external_exports.literal(true), data: schemas.entity });
  const deleteResponse = external_exports.object({ success: external_exports.literal(true), data: external_exports.object({ id: external_exports.string() }) });
  const serialize = opts.serialize ?? ((entity) => entity);
  const serializeAll = async (items) => Promise.all(items.map(async (item) => await serialize(item)));
  typed.get(path, {
    preHandler: requirePermission(permissions.read),
    schema: {
      description: `List ${path.slice(1)}`,
      security: [{ bearerAuth: [] }],
      querystring: external_exports.object({
        page: external_exports.coerce.number().int().min(1).optional(),
        limit: external_exports.coerce.number().int().min(1).max(100).optional(),
        sortBy: external_exports.string().optional(),
        sortDir: external_exports.enum(["asc", "desc"]).optional(),
        search: external_exports.string().optional()
      }),
      response: { 200: paginatedResponse }
    }
  }, async (request) => {
    const options = parseListOptions(request.query);
    const result = await service.list({ ...options, searchFields: opts.searchFields });
    return paginated(await serializeAll(result.items), computeMeta(result.page, result.limit, result.total));
  });
  typed.get(`${path}/:id`, {
    preHandler: requirePermission(permissions.read),
    schema: {
      description: `Get ${path.slice(1)} by id`,
      security: [{ bearerAuth: [] }],
      params: external_exports.object({ id: external_exports.string() }),
      response: { 200: singleResponse }
    }
  }, async (request) => {
    const { id } = request.params;
    const entity = await service.getById(id);
    return ok(await serialize(entity));
  });
  typed.post(path, {
    preHandler: requirePermission(permissions.create),
    schema: {
      description: `Create ${path.slice(1)}`,
      security: [{ bearerAuth: [] }],
      body: schemas.create,
      response: { 201: singleResponse }
    }
  }, async (request, reply) => {
    const entity = await service.create(request.body, getAuditContext(request));
    void reply.status(201);
    return ok(await serialize(entity));
  });
  typed.put(`${path}/:id`, {
    preHandler: requirePermission(permissions.update),
    schema: {
      description: `Replace ${path.slice(1)}`,
      security: [{ bearerAuth: [] }],
      params: external_exports.object({ id: external_exports.string() }),
      body: schemas.update,
      response: { 200: singleResponse }
    }
  }, async (request) => {
    const { id } = request.params;
    const entity = await service.update(id, request.body, getAuditContext(request));
    return ok(await serialize(entity));
  });
  typed.patch(`${path}/:id`, {
    preHandler: requirePermission(permissions.update),
    schema: {
      description: `Partially update ${path.slice(1)}`,
      security: [{ bearerAuth: [] }],
      params: external_exports.object({ id: external_exports.string() }),
      body: schemas.update.partial(),
      response: { 200: singleResponse }
    }
  }, async (request) => {
    const { id } = request.params;
    const entity = await service.update(id, request.body, getAuditContext(request));
    return ok(await serialize(entity));
  });
  typed.delete(`${path}/:id`, {
    preHandler: requirePermission(permissions.delete),
    schema: {
      description: `Delete ${path.slice(1)}`,
      security: [{ bearerAuth: [] }],
      params: external_exports.object({ id: external_exports.string() }),
      response: { 200: deleteResponse }
    }
  }, async (request) => {
    const { id } = request.params;
    const result = await service.delete(id, getAuditContext(request));
    return ok(result);
  });
}

// src/core/service/crud-service.ts
init_app_error();
var CrudService = class {
  constructor(cfg) {
    this.cfg = cfg;
  }
  cfg;
  get searchFields() {
    return this.cfg.searchFields;
  }
  async list(options) {
    return this.cfg.repository.list({ ...options, searchFields: this.cfg.searchFields });
  }
  async getById(id) {
    const entity = await this.cfg.repository.findById(id);
    if (!entity) throw AppError.notFound(`${this.cfg.resourceName} not found`);
    return entity;
  }
  async create(input, audit) {
    const validated = this.cfg.createSchema.parse(input);
    const data = await this.cfg.toEntity(validated);
    const entity = await this.cfg.repository.create({ data });
    await auditService.log(audit, `create:${this.cfg.resourceName}`, this.cfg.resourceName, entity.id);
    await this.cfg.afterCreate?.(entity, audit);
    return entity;
  }
  async update(id, input, audit) {
    const existing = await this.cfg.repository.findById(id);
    if (!existing) throw AppError.notFound(`${this.cfg.resourceName} not found`);
    const validated = this.cfg.updateSchema.parse(input);
    const data = await this.cfg.toEntity(validated, existing);
    const updated = await this.cfg.repository.update({ id, data });
    if (!updated) throw AppError.notFound(`${this.cfg.resourceName} not found`);
    await auditService.log(audit, `update:${this.cfg.resourceName}`, this.cfg.resourceName, id);
    return updated;
  }
  async delete(id, audit) {
    const existing = await this.cfg.repository.findById(id);
    if (!existing) throw AppError.notFound(`${this.cfg.resourceName} not found`);
    await this.cfg.beforeDelete?.(id);
    await this.cfg.repository.delete(id);
    await auditService.log(audit, `delete:${this.cfg.resourceName}`, this.cfg.resourceName, id);
    return { id };
  }
};

