var BackupRepository = class extends PrismaRepository {
  model = "backup";
  searchFields = ["label"];
  toEntity(row) {
    return {
      id: String(row.id),
      label: String(row.label),
      createdAt: this.toISO(row.createdAt),
      updatedAt: this.toISO(row.updatedAt),
      createdBy: String(row.createdBy),
      sizeBytes: Number(row.sizeBytes),
      recordCount: Number(row.recordCount),
      data: this.parseData(row.data)
    };
  }
  parseData(raw2) {
    if (!raw2) return {};
    try {
      const parsed2 = JSON.parse(String(raw2));
      if (parsed2 && typeof parsed2 === "object") {
        return parsed2;
      }
    } catch {
    }
    return {};
  }
  toCreateData(data) {
    return { ...data, data: JSON.stringify(data.data ?? {}) };
  }
};
var backupRepository = new BackupRepository();

// src/modules/backup/backup.entity.ts
init_zod();
var backupSchema = external_exports.object({
  id: external_exports.string(),
  label: external_exports.string(),
  createdAt: external_exports.string(),
  createdBy: external_exports.string(),
  sizeBytes: external_exports.number(),
  recordCount: external_exports.number()
});
var createBackupSchema = external_exports.object({
  label: external_exports.string().max(200).optional()
});
var restoreRequestSchema = external_exports.object({
  backupId: external_exports.string().min(1, "backupId is required")
});
var restorePayloadSchema = external_exports.object({
  label: external_exports.string().max(200).optional(),
  data: external_exports.record(external_exports.string(), external_exports.array(external_exports.unknown()))
});

// src/modules/backup/backup.service.ts
init_logger();
var BackupService = class {
  async createBackup(input, audit) {
    const validated = createBackupSchema.parse(input ?? {});
    const data = await this.exportAll();
    const serialized = JSON.stringify(data);
    const recordCount = Object.values(data).reduce((sum, arr) => sum + arr.length, 0);
    const backup = await backupRepository.create({
      data: {
        label: validated.label ?? `Backup ${(/* @__PURE__ */ new Date()).toLocaleString()}`,
        sizeBytes: Buffer.byteLength(serialized, "utf8"),
        recordCount,
        createdBy: audit.principal?.sub ?? "system",
        data
      }
    });
    await auditService.log(audit, "create:backup", "backup", backup.id);
    return backup;
  }
  async listBackups(options = {}) {
    return backupRepository.list({
      page: options.page,
      limit: options.limit,
      sortBy: "createdAt",
      sortDir: "desc"
    });
  }
  async getBackup(id) {
    const backup = await backupRepository.findById(id);
    if (!backup) throw AppError.notFound("backup not found");
    return backup;
  }
  async getDownload(id) {
    const backup = await this.getBackup(id);
    return {
      filename: `ledgerflow-backup-${backup.createdAt.slice(0, 10)}.json`,
      json: JSON.stringify(
        { app: "ledgerflow", version: 1, createdAt: backup.createdAt, data: backup.data },
        null,
        2
      )
    };
  }
  async deleteBackup(id, audit) {
    if (!await backupRepository.findById(id)) throw AppError.notFound("backup not found");
    await backupRepository.delete(id);
    await auditService.log(audit, "delete:backup", "backup", id);
    return { id };
  }
  /** Full restore: replaces the entire dataset with a backup's snapshot. */
  async restoreFromBackup(backupId, audit) {
    const backup = await backupRepository.findById(backupId);
    if (!backup) throw AppError.notFound("backup not found");
    await this.importAll(backup.data);
    const restored = Object.values(backup.data).reduce((sum, arr) => sum + arr.length, 0);
    await auditService.log(audit, "restore:from-backup", "restore", backupId, { restored });
    logger.info({ backupId, restored }, "Database restored from backup");
    return { restored };
  }
  /** Raw restore from an uploaded JSON payload. */
  async restoreFromPayload(data, audit) {
    if (!data || typeof data !== "object") {
      throw AppError.badRequest("Invalid restore payload");
    }
    await this.importAll(data);
    const restored = Object.values(data).reduce((sum, arr) => sum + (Array.isArray(arr) ? arr.length : 0), 0);
    await auditService.log(audit, "restore:from-payload", "restore", void 0, { restored });
    logger.info({ restored }, "Database restored from payload");
    return { restored };
  }
  /** Serialize the full database snapshot from Prisma. */
  async exportAll() {
    const { prisma: prisma2 } = await Promise.resolve().then(() => (init_prisma(), prisma_exports));
    const { resetCompanyCache: resetCompanyCache2 } = await Promise.resolve().then(() => (init_company(), company_exports));
    resetCompanyCache2();
    const tables = [
      "company",
      "permission",
      "role",
      "rolePermission",
      "user",
      "authSession",
      "party",
      "category",
      "unit",
      "product",
      "warehouse",
      "stockItem",
      "stockMovement",
      "invoice",
      "invoiceLine",
      "invoicePayment",
      "treasuryAccount",
      "treasuryTransaction",
      "account",
      "costCenter",
      "journalEntry",
      "journalDetail",
      "asset",
      "report",
      "setting",
      "backup"
    ];
    const db = prisma2;
    const out = {};
    for (const table of tables) {
      const rows = await db[table].findMany();
      out[table] = rows;
    }
    return out;
  }
  /** Wipe and re-import a snapshot into Prisma (inside one transaction). */
  async importAll(data) {
    const { runInTransaction: runInTransaction2 } = await Promise.resolve().then(() => (init_prisma(), prisma_exports));
    const { getDb: getDb2 } = await Promise.resolve().then(() => (init_prisma(), prisma_exports));
    const { resetCompanyCache: resetCompanyCache2 } = await Promise.resolve().then(() => (init_company(), company_exports));
    if (!data || typeof data !== "object") throw AppError.badRequest("Invalid restore payload");
    await runInTransaction2(async () => {
      const deleteTables = [
        "journalDetail",
        "journalEntry",
        "asset",
        "costCenter",
        "account",
        "invoicePayment",
        "invoiceLine",
        "invoice",
        "treasuryTransaction",
        "treasuryAccount",
        "stockMovement",
        "stockItem",
        "warehouse",
        "product",
        "unit",
        "category",
        "party",
        "authSession",
        "user",
        "rolePermission",
        "role",
        "permission",
        "company",
        "report",
        "setting",
        "backup"
      ];
      const createTables = [
        "company",
        "permission",
        "role",
        "rolePermission",
        "user",
        "authSession",
        "party",
        "category",
        "unit",
        "product",
        "warehouse",
        "stockItem",
        "stockMovement",
        "account",
        "costCenter",
        "asset",
        "journalEntry",
        "journalDetail",
        "treasuryAccount",
        "treasuryTransaction",
        "invoice",
        "invoiceLine",
        "invoicePayment",
        "report",
        "setting",
        "backup"
      ];
      const db = getDb2();
      for (const table of deleteTables) {
        await db[table].deleteMany();
      }
      for (const table of createTables) {
        const rows = data[table] ?? [];
        if (rows.length === 0) continue;
        await db[table].createMany({ data: rows });
      }
      resetCompanyCache2();
    });
  }
};
var backupService = new BackupService();

// src/modules/backup/backup.controller.ts
function registerBackupController(app) {
  const typed = app.withTypeProvider();
  typed.post("/backup", {
    preHandler: requirePermission(PERMISSIONS["backup:create"]),
    schema: {
      description: "Create a full database backup",
      security: [{ bearerAuth: [] }],
      body: createBackupSchema,
      response: { 201: external_exports.object({ success: external_exports.literal(true), data: backupSchema }) }
    }
  }, async (request, reply) => {
    const backup = await backupService.createBackup(request.body ?? {}, getAuditContext(request));
    void reply.status(201);
    return ok(backup);
  });
  typed.get("/backup", {
    preHandler: requirePermission(PERMISSIONS["backup:read"]),
    schema: {
      description: "List backups",
      security: [{ bearerAuth: [] }],
      querystring: external_exports.object({ page: external_exports.coerce.number().optional(), limit: external_exports.coerce.number().optional() }),
      response: { 200: external_exports.object({ success: external_exports.literal(true), data: external_exports.array(backupSchema), meta: external_exports.any() }) }
    }
  }, async (request) => {
    const q = request.query;
    const page = Number(q.page ?? 1);
    const limit = Number(q.limit ?? 20);
    const result = await backupService.listBackups({ page, limit });
    return paginated(result.items, computeMeta(result.page, result.limit, result.total));
  });
  typed.get("/backup/:id", {
    preHandler: requirePermission(PERMISSIONS["backup:read"]),
    schema: {
      description: "Get backup metadata",
      security: [{ bearerAuth: [] }],
      params: external_exports.object({ id: external_exports.string() }),
      response: { 200: external_exports.object({ success: external_exports.literal(true), data: backupSchema }) }
    }
  }, async (request) => {
    const { id } = request.params;
    return ok(await backupService.getBackup(id));
  });
  typed.get("/backup/:id/download", {
    preHandler: requirePermission(PERMISSIONS["backup:read"]),
    schema: {
      description: "Download a backup as JSON",
      security: [{ bearerAuth: [] }],
      params: external_exports.object({ id: external_exports.string() }),
      response: { 200: external_exports.any() }
    }
  }, async (request, reply) => {
    const { id } = request.params;
    const { filename, json } = await backupService.getDownload(id);
    void reply.header("Content-Type", "application/json");
    void reply.header("Content-Disposition", `attachment; filename="${filename}"`);
    return JSON.parse(json);
  });
  typed.delete("/backup/:id", {
    preHandler: requirePermission(PERMISSIONS["backup:delete"]),
    schema: {
      description: "Delete a backup",
      security: [{ bearerAuth: [] }],
      params: external_exports.object({ id: external_exports.string() }),
      response: { 200: external_exports.object({ success: external_exports.literal(true), data: external_exports.object({ id: external_exports.string() }) }) }
    }
  }, async (request) => {
    const { id } = request.params;
    return ok(await backupService.deleteBackup(id, getAuditContext(request)));
  });
  typed.post("/restore/from-backup", {
    preHandler: requirePermission(PERMISSIONS["restore:create"]),
    schema: {
      description: "Restore the database from an existing backup",
      security: [{ bearerAuth: [] }],
      body: restoreRequestSchema,
      response: { 200: external_exports.object({ success: external_exports.literal(true), data: external_exports.object({ restored: external_exports.number() }) }) }
    }
  }, async (request) => {
    return ok(await backupService.restoreFromBackup(request.body.backupId, getAuditContext(request)));
  });
  typed.post("/restore/from-payload", {
    preHandler: requirePermission(PERMISSIONS["restore:create"]),
    schema: {
      description: "Restore the database from an uploaded JSON payload",
      security: [{ bearerAuth: [] }],
      body: restorePayloadSchema,
      response: { 200: external_exports.object({ success: external_exports.literal(true), data: external_exports.object({ restored: external_exports.number() }) }) }
    }
  }, async (request) => {
    return ok(await backupService.restoreFromPayload(request.body.data, getAuditContext(request)));
  });
}

